use serde_json::json;use std::fs;
fn packages(s:&str)->Vec<&str>{s.split("[[package]]").skip(1).map(str::trim).collect()}
fn main(){let a=fs::read_to_string("/home/ubuntu/src/zk-tools/zopro/Cargo.lock").unwrap();let b=fs::read_to_string("/tmp/zopro-single-epoch-advancer/candidate/Cargo.lock").unwrap();let(a,b)=(packages(&a),packages(&b));assert_eq!(a.len(),b.len());let mut changed=0;for(x,y)in a.iter().zip(&b){if x==y{continue}assert!(x.starts_with("name = \"crossbeam-epoch\"\nversion = \"0.9.21\""));let stripped=x.lines().filter(|l|!l.starts_with("source = ")&&!l.starts_with("checksum = ")).collect::<Vec<_>>().join("\n");assert_eq!(stripped,*y);changed+=1;}assert_eq!(changed,1);let out=json!({"packages":a.len(),"identical_package_entries":a.len()-1,"changed_entries":1,"only_change":"epoch registry source/checksum removed for path patch","versions_and_dependency_edges_unchanged":true});fs::write("/tmp/zopro-single-epoch-advancer/lock-audit.json",serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Runtime lock: {}packages,{}identical,epoch path-only",a.len(),a.len()-1);}
